package com.badrulamin.University_Management.service; import com.badrulamin.University_Management.exception.ResourceNotFoundException;  import com.badrulamin.University_Management.entity.FacultyDivision; import com.badrulamin.University_Management.repository.FacultyDivisionRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable;  @Service @RequiredArgsConstructor public class FacultyDivisionService {      private final FacultyDivisionRepository facultyDivisionRepository;      public Page<FacultyDivision> findAll(Pageable pageable) {         return facultyDivisionRepository.findAll(pageable);     }      public FacultyDivision findById(Long id) {         return facultyDivisionRepository.findById(id)                 .orElseThrow(() -> new ResourceNotFoundException("FacultyDivision", "id", id));     }      public FacultyDivision save(FacultyDivision facultyDivision) {         return facultyDivisionRepository.save(facultyDivision);     }      public FacultyDivision update(Long id, FacultyDivision facultyDivision) {         findById(id);         facultyDivision.setId(id);         return facultyDivisionRepository.save(facultyDivision);     }      public void delete(Long id) {         findById(id);         facultyDivisionRepository.deleteById(id);     } }